python3 -c "
import sys
try:
    from pypdf import PdfReader
except Exception:
    from PyPDF2 import PdfReader
for f in ['/Users/nstewart/Downloads/Fiorn.pdf','/Users/nstewart/Downloads/Loric.pdf']:
    print('=====',f,'=====')
    r=PdfReader(f)
    for i,p in enumerate(r.pages):
        print(f'---PAGE {i+1}---')
        print(p.extract_text())
"

python3 -c "
from pypdf import PdfReader
for f in ['/Users/nstewart/Downloads/Fiorn.pdf','/Users/nstewart/Downloads/Loric.pdf']:
    print('=====',f,'=====')
    r=PdfReader(f)
    fields=r.get_form_text_fields() or {}
    for k,v in fields.items():
        if v is not None and str(v).strip():
            print(repr(k),'=',repr(v))
    print('---all fields incl checkboxes---')
    af=r.get_fields() or {}
    for k,v in af.items():
        val=v.get('/V') if hasattr(v,'get') else None
        if val not in (None,'','Off'):
            print(repr(k),'->',repr(val))
"
